function validate([nums, edges]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'The tree needs 1 to 100000 nodes.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'Each value is an integer from 1 to 50.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must hold exactly n - 1 pairs.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge endpoints must be node labels from 0 to n - 1.';
    if (u === v) return 'An edge must join two different nodes.';
    const a = find(u), b = find(v);
    if (a === b) return 'The edges must form a tree (no cycles).';
    root[a] = b;
  }
  return null;
}

