function getCoprimes(nums, edges) {
  const n = nums.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    graph[u].push(v);
    graph[v].push(u);
  }
  const gcd = (x, y) => (y === 0 ? x : gcd(y, x % y));
  const coprimes = Array.from({ length: 51 }, () => []);
  for (let x = 1; x <= 50; x++) {
    for (let y = 1; y <= 50; y++) {
      if (gcd(x, y) === 1) coprimes[x].push(y);
    }
  }

  const onPath = Array.from({ length: 51 }, () => []);
  const depth = new Array(n).fill(0);
  const answer = new Array(n).fill(-1);
  const stack = [[0, -1, false]];

  while (stack.length > 0) {
    const [node, parent, leaving] = stack.pop();
    if (leaving) {
      onPath[nums[node]].pop();
      continue;
    }
    for (const value of coprimes[nums[node]]) {
      const holders = onPath[value];
      if (holders.length === 0) continue;
      const nearest = holders[holders.length - 1];
      if (answer[node] === -1 || depth[nearest] > depth[answer[node]]) {
        answer[node] = nearest;
      }
    }
    onPath[nums[node]].push(node);
    stack.push([node, parent, true]);
    for (const child of graph[node]) {
      if (child === parent) continue;
      depth[child] = depth[node] + 1;
      stack.push([child, node, false]);
    }
  }
  return answer;
}

