function getCoprimes(nums, edges) {
  const n = nums.length;
  const neighbours = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { neighbours[u].push(v); neighbours[v].push(u); }
  const parentOf = new Array(n).fill(-1);
  const seen = new Array(n).fill(false);
  const queue = [0];
  seen[0] = true;
  for (let head = 0; head < queue.length; head++) {
    for (const next of neighbours[queue[head]]) {
      if (!seen[next]) { seen[next] = true; parentOf[next] = queue[head]; queue.push(next); }
    }
  }
  const divisor = (x, y) => { while (y) [x, y] = [y, x % y]; return x; };
  const result = [];
  for (let i = 0; i < n; i++) {
    let up = parentOf[i];
    while (up !== -1 && divisor(nums[i], nums[up]) !== 1) up = parentOf[up];
    result.push(up);
  }
  return result;
}

