function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 9);
  const top = large || rand() < 0.5 ? 50 : 1 + Math.floor(rand() * 12);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  // Random labels, so the root (label 0) can sit anywhere in the shape.
  const labels = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [labels[i], labels[j]] = [labels[j], labels[i]]; }
  // Large trees get a long spine so the search goes deep.
  const spine = large ? 500 + Math.floor(rand() * 1500) : 0;
  const edges = [];
  for (let i = 1; i < n; i++) {
    const attach = i < spine ? i - 1 : Math.floor(rand() * i);
    edges.push(rand() < 0.5 ? [labels[attach], labels[i]] : [labels[i], labels[attach]]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [nums, edges];
}
